"""Internal operational forecast service. Reports are generated by the training CLI."""

import os
import secrets
from fastapi import FastAPI, Header, HTTPException
from .store import forecast, manifest, ForecastUnavailable

app = FastAPI(title="DAI synthetic operational forecasting", version="1.0.0")


@app.get("/health")
def health():
    try:
        info = manifest()
        return {
            "status": "trained",
            "models_trained": True,
            "version": info["version"],
            "data_label": info["data_label"],
            "facility_count": info["facility_count"],
        }
    except ForecastUnavailable:
        return {
            "status": "not_trained",
            "models_trained": False,
            "data_label": "Simulated on synthetic data",
        }


@app.get("/v1/forecasts/{hospital_id}")
def predictions(hospital_id: str, x_dai_ml_token: str = Header(default="")):
    token = os.getenv("DAI_ML_SERVICE_TOKEN")
    if not token:
        raise HTTPException(503, "Internal ML service token is not configured")
    if not secrets.compare_digest(x_dai_ml_token, token):
        raise HTTPException(401, "Internal service authentication required")
    try:
        return forecast(hospital_id)
    except ForecastUnavailable as exc:
        raise HTTPException(503, str(exc))
